			//화면 하단 '취소'버튼 클릭시 DS를 REVERT처리
			function setRevert(){

			    app.lookup("dsAftfctMngList") .revert(); //사후관리
			    app.lookup("dsAftfctTrmnList").revert(); //사후종료

			    setDsAftfctMngRowCnt();

			    if(vcEmbDefInfo == null) {
			        vcEmbDefInfo = app.lookup("embapp5");
			    }

			    if(vcEmbDefInfo.getEmbeddedAppInstance() != null) {
			        vcEmbDefInfo.getEmbeddedAppInstance().getAllDataControls().forEach(function(ctrl) {
			            if(ctrl.type == "dataset") {
			                ctrl.revert();
			            }
			        });
			    }
			}
			exports.setRevert = setRevert;

