			/*
			 * 탭 폴더에서 selection-change 이벤트 발생 시 호출.
			 * Tab Item을 선택한 후에 발생하는 이벤트.
			 */
			function onFldCaseReasseSelectionChange(e){

			    util.DataMap.clear(app, "dmSearch");
			    util.DataMap.setValue(app, "dmSearch", "CASE_MNG_NO"   , sCaseMngNo);
			    util.DataMap.setValue(app, "dmSearch", "CASE_MNG_ODRNO", sCaseMngOdrno);

			    var submission = null;
			    var callFunc   = "";

			    var vnSeltTabId = util.Tab.getSelectedId(app, "fldCaseReasse");

			    //사후관리등록
			    if(vnSeltTabId == "1") {
			        util.DataSet.clear(app, "dsAftfctMngList");

			        submission = "subAftfctMngList";
			        callFunc   = "setDsAftfctMngRowCnt()";
			    }
			    //사후관리종결
			    else if(vnSeltTabId == "2") {
			        util.DataSet.clear(app, "dsAftfctTrmnList");

			        submission = "subAftfctTrmnList";
			    }

			    //조회 서브미션 호출
			    util.Submit.send(app, submission, function(pbSuccess) {
			        if (pbSuccess) {
			            //조회되었습니다.
			            util.Msg.notify(app, "INF-M001");

			            eval(callFunc);

			            if(vnSeltTabId == "1") {
			                if(util.DataSet.getRowCount(app, "dsAftfctMngList") > 0) {
			                    util.Grid.selectRow(app, "grdAftfctMngList", 0); 

			                    app.lookup("cmnMultifileupload").getFiles();   
			                }
			            } else {
			                var objDs = app.lookup("dsAftfctTrmnList");
			                if(objDs.getRowCount() == 0) {
			                    objDs.addRow();
			                    objDs.setValue(0, "CASE_MNG_NO"         , sCaseMngNo);
			                    objDs.setValue(0, "CASE_MNG_ODRNO"      , sCaseMngOdrno);
			                    objDs.setValue(0, "TRPR_INFO_NO"        , sTrprInfoNo);
			                    objDs.setValue(0, "AFTFCT_TRMN_APLY_YMD", vsToday);
			                    objDs.setValue(0, "AFTFCT_TRMN_SRNG_YMD", vsToday);
			                }
			            }
			        }

			        util.Control.redraw(app, "fldCaseReasse");
			    });
			}

